import sys
from math import gcd
from collections import defaultdict

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        x, y = map(int, sys.stdin.readline().split())
        adj[x].append(y)
        adj[y].append(x)

    parent = [0]*(n+1)
    depth = [0]*(n+1)
    size = [0]*(n+1)
    gcd_path = [0]*(n+1)

    stack = [(1, 0, 0)]
    while stack:
        u, p, d = stack.pop()
        parent[u] = p
        depth[u] = d
        size[u] = 1
        gcd_path[u] = a[u-1]
        for v in adj[u]:
            if v != p:
                stack.append((v, u, d+1))

    res = defaultdict(int)
    for u in range(1, n+1):
        for v in range(u, n+1):
            if u == v:
                res[a[u-1]] += 1
                continue
            x, y = u, v
            if depth[x] < depth[y]:
                x, y = y, x
            current_gcd = 0
            while x != y:
                if depth[x] > depth[y]:
                    current_gcd = gcd(current_gcd, gcd_path[x])
                    x = parent[x]
                else:
                    current_gcd = gcd(current_gcd, gcd_path[y])
                    y = parent[y]
            current_gcd = gcd(current_gcd, gcd_path[x])
            res[current_gcd] += 1

    for i in range(1, 2*10**5 + 1):
        if res[i] > 0:
            print(i, res[i])

if __name__ == '__main__':
    main()
